/**
 * Model-facing artifacts the code panes show: rendered CASE FACTS, the strict tool schemas, the plan, the policy
 * table, the recipe. Generated by `make tour-payloads` (apps/api/scripts/tour_payloads.py) from the canonical seed;
 * each file's header says where it came from, and an API test fails if a committed file drifts from the code.
 * Loaded lazily: they are text, and only the step that shows one needs it.
 */
const FILES = import.meta.glob<string>('./payloads/*.txt', { query: '?raw', import: 'default' })

export const PAYLOADS = ['prompt_4821', 'plan_4821', 'tools', 'policy', 'guard', 'recipe_resubmit', 'case_4744', 'plan_4744', 'models', 'router', 'mockonly', 'search'] as const
export type PayloadName = (typeof PAYLOADS)[number]

export async function loadPayload(name: PayloadName): Promise<string> {
  const load = FILES[`./payloads/${name}.txt`]
  if (!load) throw new Error(`payload ${name} is missing; run make tour-payloads`)
  return load()
}

export const hasPayload = (name: PayloadName) => `./payloads/${name}.txt` in FILES
